pragma solidity >=0.0.0;

import "../lib/Math.sol";

/// @title A small vault for exploring compiler output
/// @dev λ — UTF-8 source locations stay accurate.
contract Vault {
    uint256 public balance;
    address public immutable owner;

    event Deposited(address indexed sender, uint256 amount);

    constructor() {
        owner = msg.sender;
    }

    function deposit(uint256 amount) external {
        uint256 next = balance + amount;
        assert(next >= balance);
        balance = next;
        emit Deposited(msg.sender, amount);
    }

    function preview(uint256 amount) external pure returns (uint256) {
        uint256 unused = amount;
        assert(amount == amount);
        assert(amount > 1);
        return Math.twice(amount);
    }
}

